def candidate(grid, k):
    n = len(grid)
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    min_path = None

    def backtrack(row, col, path):
        nonlocal min_path
        if len(path) == k:
            if min_path is None or path < min_path:
                min_path = path
            return
        if min_path is not None and path >= min_path:
            return
        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < n and 0 <= new_col < n:
                backtrack(new_row, new_col, path + [grid[new_row][new_col]])

    for row in range(n):
        for col in range(n):
            backtrack(row, col, [grid[row][col]])

    return min_path

def heap_sort(arr):
    n = len(arr)

    # Build a max heap
    for i in range(n // 2 - 1, -1, -1):
        heapify(arr, n, i)

    # Extract elements from the heap one by one
    for i in range(n - 1, 0, -1):
        arr[0], arr[i] = arr[i], arr[0]
        heapify(arr, i, 0)

    return arr

def heapify(arr, n, i):
    largest = i
    left = 2 * i + 1
    right = 2 * i + 2

    if left < n and arr[left] > arr[largest]:
        largest = left

    if right < n and arr[right] > arr[largest]:
        largest = right

    if largest != i:
        arr[i], arr[largest] = arr[largest], arr[i]
        heapify(arr, n, largest)

def count_element_freq(nested_tuple):
    element_freq = {}
    for element in nested_tuple:
        if isinstance(element, tuple):
            for sub_element in count_element_freq(element):
                element_freq[sub_element] = element_freq.get(sub_element, 0) + 1
        else:
            element_freq[element] = element_freq.get(element, 0) + 1
    return element_freq
